/**
 * Tests for the guard-denial repetition counter (#3422).
 *
 * Real fs under a temp home — the ledger surviving across hook PROCESSES is
 * the whole point of the feature, so an in-memory double would test nothing.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import {
  DENIAL_TTL_MS,
  getDenialLedgerPath,
  pruneLedger,
  recordDenial,
  type DenialLedger,
} from '../../lib/denial-counter.js';

const REPO = 'orchestkit';
const SESSION = 'sess-abc';
const CMD = 'git add -A && git commit -m "feat: x"';

let home: string;

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), 'denials-'));
});

afterEach(() => {
  rmSync(home, { recursive: true, force: true });
});

const record = (cmd = CMD, now = Date.now(), session = SESSION): number =>
  recordDenial(cmd, REPO, session, now, home);

describe('recordDenial', () => {
  it('counts the first denial as 1', () => {
    expect(record()).toBe(1);
  });

  it('escalates on the second byte-identical denial', () => {
    expect(record()).toBe(1);
    expect(record()).toBe(2);
  });

  it('keeps counting past the second', () => {
    for (let i = 1; i <= 8; i++) expect(record()).toBe(i);
  });

  it('starts over when the command changes shape', () => {
    expect(record(CMD)).toBe(1);
    expect(record(CMD)).toBe(2);
    // The desired response to a denial is a differently-shaped command; that
    // must read as a fresh attempt, not as more of the same loop.
    expect(record(`git -C /abs/path add -A && git commit -m "feat: x"`)).toBe(1);
  });

  it('tracks two different commands independently', () => {
    expect(record('git commit -m a')).toBe(1);
    expect(record('git push')).toBe(1);
    expect(record('git commit -m a')).toBe(2);
  });

  it('does not pool separate sessions together', () => {
    expect(record(CMD, Date.now(), 'sess-one')).toBe(1);
    expect(record(CMD, Date.now(), 'sess-two')).toBe(1);
  });

  it('persists across calls in a real file', () => {
    record();
    const path = getDenialLedgerPath(REPO, SESSION, home);
    expect(existsSync(path)).toBe(true);
    const ledger: DenialLedger = JSON.parse(readFileSync(path, 'utf8'));
    expect(Object.values(ledger)[0].count).toBe(1);
  });

  it('forgets an entry older than the TTL', () => {
    const t0 = Date.now();
    expect(record(CMD, t0)).toBe(1);
    expect(record(CMD, t0 + DENIAL_TTL_MS + 1)).toBe(1);
  });

  it('still escalates just inside the TTL', () => {
    const t0 = Date.now();
    expect(record(CMD, t0)).toBe(1);
    expect(record(CMD, t0 + DENIAL_TTL_MS - 1000)).toBe(2);
  });

  it('disables tracking without a session id', () => {
    expect(recordDenial(CMD, REPO, '', Date.now(), home)).toBe(1);
    expect(recordDenial(CMD, REPO, '', Date.now(), home)).toBe(1);
  });

  it('fails open on a corrupt ledger instead of throwing', () => {
    const path = getDenialLedgerPath(REPO, SESSION, home);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, '{ not json');
    expect(record()).toBe(1);
  });

  it('fails open on a ledger holding a JSON array', () => {
    const path = getDenialLedgerPath(REPO, SESSION, home);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, '[1,2,3]');
    expect(record()).toBe(1);
  });
});

describe('pruneLedger', () => {
  it('drops expired entries and keeps live ones', () => {
    const now = Date.now();
    const ledger: DenialLedger = {
      live: { count: 3, firstMs: now - 1000, lastMs: now - 1000, head: 'a' },
      expired: { count: 9, firstMs: 0, lastMs: now - DENIAL_TTL_MS - 1, head: 'b' },
    };
    expect(Object.keys(pruneLedger(ledger, now))).toEqual(['live']);
  });

  it('caps the ledger so a long session cannot grow it without bound', () => {
    const now = Date.now();
    const ledger: DenialLedger = {};
    for (let i = 0; i < 120; i++) {
      ledger[`k${i}`] = { count: 1, firstMs: now, lastMs: now - i, head: `c${i}` };
    }
    const pruned = pruneLedger(ledger, now);
    expect(Object.keys(pruned).length).toBe(50);
    // Newest survive: k0 has the most recent lastMs.
    expect(pruned.k0).toBeDefined();
    expect(pruned.k119).toBeUndefined();
  });

  it('discards malformed entries rather than trusting them', () => {
    const now = Date.now();
    const ledger = {
      bad: { count: 2 },
      good: { count: 1, firstMs: now, lastMs: now, head: 'x' },
    } as unknown as DenialLedger;
    expect(Object.keys(pruneLedger(ledger, now))).toEqual(['good']);
  });
});
